import { readFile, writeFile, mkdir, copyFile } from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { createHash } from 'node:crypto';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');

// Transform only explicit, non-nested slots generated by our React components.
// A depth counter handles nested elements; text containing < is HTML-escaped by React.
export function compileLiveTemplate(html) {
  const slot = /<([a-z][a-z0-9]*)\b[^>]*\bdata-live-slot="([a-z-]+:[a-z0-9-]+)"[^>]*>/g;
  let output = '', cursor = 0, match;
  while ((match = slot.exec(html))) {
    const tags = new RegExp(`<(/?)${match[1]}\\b[^>]*>`, 'g');
    tags.lastIndex = slot.lastIndex;
    let depth = 1, end;
    while ((end = tags.exec(html))) {
      depth += end[1] ? -1 : 1;
      if (depth === 0) break;
    }
    if (!end) throw new Error(`Unclosed live slot ${match[2]}`);
    if (html.slice(slot.lastIndex, end.index).includes('data-live-slot=')) throw new Error(`Nested live slot ${match[2]}`);
    output += html.slice(cursor, slot.lastIndex) + `<!--LIVE:${match[2]}-->`;
    cursor = end.index;
    slot.lastIndex = tags.lastIndex;
  }
  return compileVisibility(output + html.slice(cursor));
}

function compileVisibility(html) {
  const marker = /<([a-z][a-z0-9]*)\b[^>]*\bdata-live-visible="([a-z0-9-]+)"[^>]*>/g;
  let output = '', cursor = 0, match;
  while ((match = marker.exec(html))) {
    const tags = new RegExp(`<(/?)${match[1]}\\b[^>]*>`, 'g');
    tags.lastIndex = marker.lastIndex;
    let depth = 1, end;
    while ((end = tags.exec(html))) {
      depth += end[1] ? -1 : 1;
      if (!depth) break;
    }
    if (!end) throw new Error(`Unclosed visibility marker ${match[2]}`);
    if (html.slice(marker.lastIndex, end.index).includes('data-live-visible=')) throw new Error(`Nested visibility marker ${match[2]}`);
    output += html.slice(cursor, match.index) + `<!--VISIBLE:${match[2]}-->` + html.slice(match.index, tags.lastIndex) + `<!--/VISIBLE:${match[2]}-->`;
    cursor = tags.lastIndex;
    marker.lastIndex = cursor;
  }
  return output + html.slice(cursor);
}

export async function prepareLiveEditor(distRoot = path.join(root, 'dist/client')) {
  const routes = {};
  const content = path.join(distRoot, 'content');
  const icons = JSON.parse(await readFile(path.join(content, 'icons.json'), 'utf8'));
  const articles = JSON.parse(await readFile(path.join(content, 'articles.json'), 'utf8'));
  const paths = ['/', '/collection', '/articles', ...icons.filter(x=>x.published !== false).map(x=>`/icons/${x.slug}`), ...articles.filter(x=>x.published !== false).map(x=>`/articles/${x.slug}`)];
  const templatesRoot = path.join(distRoot, '.live-templates');
  await mkdir(templatesRoot, {recursive:true});
  for (const route of paths) {
    const file = path.join(distRoot, route.slice(1), 'index.html');
    const template = compileLiveTemplate(await readFile(file, 'utf8'));
    const name = createHash('sha256').update(route).digest('hex')+'.html';
    await writeFile(path.join(templatesRoot, name), template);
    routes[route] = name;
  }
  await writeFile(path.join(templatesRoot,'routes.json'), JSON.stringify(routes));
  for (const directory of ['.live-templates', '.editor-state']) {
    await mkdir(path.join(distRoot, directory), {recursive:true});
    await writeFile(path.join(distRoot, directory, '.htaccess'), 'Deny from all\n');
  }
  await writeFile(path.join(content, '.htaccess'), '<IfModule mod_headers.c>\nHeader set Cache-Control "no-cache, must-revalidate"\n</IfModule>\n<FilesMatch "^\\.">\nDeny from all\n</FilesMatch>\n');
  const editorRoot = path.join(distRoot, 'corona/admin/text-editor');
  await mkdir(editorRoot, {recursive:true});
  for (const file of ['editor.php','editor.css','store.php','render.php','pricing.php']) await copyFile(path.join(root,'server/text-editor',file), path.join(editorRoot,file));
  await writeFile(path.join(distRoot,'corona/admin/content.php'), "<?php\nrequire dirname(__FILE__).'/text-editor/editor.php';\n");
  await copyFile(path.join(root,'server/text-editor/content-page.php'), path.join(distRoot,'content-page.php'));
  await copyFile(path.join(root,'server/text-editor/content-sitemap.php'), path.join(distRoot,'content-sitemap.php'));
  // Keep canonical redirects ahead of dispatch, preserve existing aliases and all legacy PHP.
  const apachePath = path.join(distRoot,'.htaccess');
  let apache = await readFile(apachePath,'utf8');
  const escaped = value => value.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  const rules = [
    'RewriteRule ^sitemap\\.xml$ content-sitemap.php [L]',
    'RewriteRule ^\\.(?:live-templates|editor-state)(?:/|$) - [F,L]',
    'RewriteCond %{QUERY_STRING} ^COM=articles_list$',
    'RewriteRule ^corona/admin/index\\.php$ /corona/admin/content.php?kind=articles [R=302,L]',
    'RewriteCond %{QUERY_STRING} ^(?:COM=shop_list)?$',
    'RewriteRule ^corona/admin/(?:index\\.php)?$ /corona/admin/content.php?kind=icons [R=302,L]',
    ...paths.flatMap(route => {
      const pattern = escaped(route.slice(1));
      return [
        `RewriteRule ^${pattern}${route === '/' ? '' : '/'}index\\.html$ https://iconamaster.ru${route} [R=301,L,NE]`,
        ...(route === '/' ? [] : [`RewriteRule ^${pattern}/$ https://iconamaster.ru${route} [R=301,L,NE]`]),
        `RewriteRule ^${pattern}$ content-page.php?route=${route} [L]`,
      ];
    }),
  ];
  apache = apache.replace('RewriteEngine On', 'RewriteEngine On\n\n# Live text from local content; query strings cannot override the route.\n'+rules.join('\n'));
  await writeFile(apachePath, apache);
  return paths.length;
}
if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) console.log(`Prepared ${await prepareLiveEditor()} live content pages and Corona editor.`);
